"frustration": {
    "type": "score",
    "instructions": "How frustrated is the customer, judged from their tone?",
    "levels": ["Calm", "Mildly annoyed", "Frustrated but civil", "Very angry or threatening to leave"]
  },

s = d["frustration"].score
if s >= 2.5:
    assign_to_senior(ticket, decision_id=d.id)      # leaning to "Very angry or threatening to leave"
elif s >= 1.5:
    flag_tone(ticket)                               # leaning to "Frustrated but civil"
